  const createShareLinkV17 = async (role='viewer') => {
  if (!active) return;

  try {
    const created = await request(
      `/api/projects/${active.id}/share-links`,
      {
        method: 'POST',
        body: JSON.stringify({ role })
      }
    );

    const item = created?.item || created;

    const shareUrl =
      item?.url ||
      item?.shareUrl ||
      item?.link ||
      (item?.token
        ? `${window.location.origin}/share/${item.token}`
        : window.location.href);

    const payload = {
      type: 'share',
      title: `NNIT Studio â€” ${active.name}`,
      message: `${active.name} Â· ${role} access`,
      url: shareUrl
    };

    const nativeBridge = (window as any).ReactNativeWebView;

    if (nativeBridge?.postMessage) {
      nativeBridge.postMessage(JSON.stringify(payload));
      setStatus('Opening Android share menuâ€¦');
    } else if (navigator.share) {
      await navigator.share({
        title: payload.title,
        text: payload.message,
        url: payload.url
      });
    } else {
      await navigator.clipboard.writeText(shareUrl);
      setStatus('Share link copied to clipboard');
    }

    await loadCollaborationV17();
  } catch (err: any) {
    setStatus(`Share failed: ${err?.message || 'Unknown error'}`);
  }
};
